","2"]],"type":"table","columns":["Objeto","Precio base","Peso","Unidades por paquete","Peso por unidad (lb)","Precio por unidad (pc)"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"}]$text_ba2dd7539bfe43ab$::jsonb,true),'{inventory,2,catalog,revision}',$text_4e07408562bedb8b$3$text_4e07408562bedb8b$::jsonb,true),'{inventory,2,rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_b507874e9dab9bc1$["official-table"]$text_b507874e9dab9bc1$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{inventory,2,rules,definition,capabilities}')cap),true),'{inventory,4,features}',$text_33444504bb0c5fb3$[{"id":"official-use","kind":"other","name":"Propiedades oficiales","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves puesto este anillo, podrás utilizar una acción para pronunciar su palabra de activación e invocar a un determinado djinn del Plano Elemental del Aire. El djinn aparecerá en un espacio sin ocupar que elijas a 36 m o menos de ti. Permanecerá mientras te concentres (como si te concentraras en un conjuro) hasta un máximo de 1 hora o hasta que sus puntos de golpe se reduzcan a 0. A continuación, regresará a su plano.\n\nMientras esté invocado, el djinn será amistoso contigo y tus compañeros. Obedecerá cualquier orden que le des, utilices el idioma que utilices. Si no le das ninguna, el djinn se defenderá de los atacantes, pero no llevará a cabo ninguna otra acción.\n\nUna vez que se haya ido, no se podrá volver a invocarlo durante 24 horas. El anillo se volverá no mágico si el djinn muere.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_33444504bb0c5fb3$::jsonb,true),'{inventory,4,catalog,revision}',$text_4e07408562bedb8b$3$text_