if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='monster' and content_key='gm:monster:eng:1526c61732bc5215f39efdd8' and md5(to_jsonb(t)::text)='ec5d62dd89ef6f8c4becf47d109899f1')then raise exception 'ITEM_TEXT_CONFLICT:merchant:gm:monster:eng:1526c61732bc5215f39efdd8';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(payload,'{inventory,3,features}',$text_541b5e2a819fefef$[{"id":"official-use","kind":"other","name":"Propiedades oficiales","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este mejunje parece, huele y sabe como una poción de curación u otra poción beneficiosa. Sin embargo, en realidad es un veneno enmascarado con magia de ilusionismo. Un conjuro identificar revelará su verdadera naturaleza.\n\nSi te bebes la poción, sufrirás 3d6 de daño de veneno y deberás superar una tirada de salvación de Constitución con CD 13 o quedarás envenenado. Al principio de cada uno de tus turnos mientras estés envenenado de esta forma, sufrirás 3d6 de daño de veneno. Al final de cada uno de tus turnos, podrás repetir la tirada de salvación. Si la superas, el daño de veneno que sufras en los turnos posteriores se reducirá en 1d6. El veneno dejará de tener efecto cuando el daño se reduzca a 0.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_541b5e2a819fefef$::jsonb,true),'{inventory,3,catalog,revision}',$text_4e07408562bedb8b$3$text_4e07408562bedb8b$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='monster' and content_key='gm:monster:eng:1526c61732bc5215f39efdd8';
