nition,capabilities}')cap),true),'{inventory,3,description}',$text_1efb0a82511fd504$"Objeto · Precio base · Peso\nJabón · 2 pc · —\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_1efb0a82511fd504$::jsonb,true),'{inventory,3,rules,definition,description}',$text_93041a9fb83c0315$[{"id":"official-table","rows":[["Jabón","2 pc","—"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"}]$text_93041a9fb83c0315$::jsonb,true),'{inventory,3,catalog,revision}',$text_4e07408562bedb8b$3$text_4e07408562bedb8b$::jsonb,true),'{inventory,3,rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_b507874e9dab9bc1$["official-table"]$text_b507874e9dab9bc1$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{inventory,3,rules,definition,capabilities}')cap),true),'{inventory,4,description}',$text_5479001584507f1e$"Objeto · Precio base · Peso\nReloj de arena · 25 po · 1 lb\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_5479001584507f1e$::jsonb,true),'{inventory,4,rules,definition,description}',$text_6188d493dbf01d15$[{"id":"official-table","rows":[["Reloj de arena","25 po","1 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"}]$text_6188d493dbf01d15$::jsonb,true),'{inventory,4,catalog,revision}',$text_4e07408562bedb8b$3$text_4e07408562bedb8b$::jsonb,true),'{inventory,4,rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_b507874e9dab9bc1$["official-table"]$text_b507874e9dab9bc1$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{inventory,4,rules,definition,capabilities}')cap),true),'{inventory,5,description}',$text_2467095af0cbf025$"Objeto · Precio base · Peso\nSuministros de cervecero · 20 po · 9 lb\n\nHerramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.\n\nLas herramientas te permiten realizar algo que de otra forma estaría fuera de tu alcance, como fabricar o reparar un objeto, falsificar un documento o forzar una cerradura. Tu raza, clase, trasfondo o dotes pueden hacerte competente con ciertas herramientas. La competencia con una herramienta te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dicha herramienta. Hay que tener en cuenta que el uso de herramientas no está atado a una única característica, ya que la competencia con ellas representa un conocimiento amplio sobre su empleo. De este modo, tu GM podría pedirte que realices una prueba de Destreza para tallar detalles delicados con unas herramientas de ebanista, mientras que esculpir algo a partir de una madera especialmente dura podría requerir una prueba de Fuerza.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_2467095af0cbf025$::jsonb,true),'{inventory,5,features}',$text_2b2bca0e5c7a5789$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Herramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_2b2bca0e5c7a5789$::jsonb,true),'{inventory,5,rules,definition,description}',$text_088f854cd8c99670$[{"id":"official-table","rows":[["Suministros de cervecero","20 po","9 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Herramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"tools-context-general","text":"Las herramientas te permiten realizar algo que de otra forma estaría fuera de tu alcance, como fabricar o reparar un objeto, falsificar un documento o forzar una cerradura. Tu raza, clase, trasfondo o dotes pueden hacerte competente con ciertas herramientas. La competencia con una herramienta te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dicha herramienta. Hay que tener en cuenta que el uso de herramientas no está atado a una única característica, ya que la competencia con ellas representa un conocimiento amplio sobre su empleo. De este modo, tu GM podría pedirte que realices una prueba de Destreza para tallar detalles delicados con unas herramientas de ebanista, mientras que esculpir algo a partir de una madera especialmente dura podría requerir una prueba de Fuerza.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-tools-context"],"provenance":"official-spanish"}]$text_088f854cd8c99670$::jsonb,true),'{inventory,5,catalog,revision}',$text_4b227777d4dd1fc6$4$text_4b227777d4dd1fc6$::jsonb,true),'{inventory,5,rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_ee76d66ef5f1117d$["official-table","official-rules-0","tools-context-general"]$text_ee76d66ef5f1117d$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{inventory,5,rules,definition,capabilities}')cap),true),'{inventory,6,description}',$text_6124846e52dfb250$"Objeto · Precio base · Peso · Daño base · Propiedades · Bonificación mágica\nEspadón de lengua de fuego · 50 po (solo objeto mundano base; no es el precio de la variante mágica) · 6 lb · 2d6 cortante · Pesada, A dos manos · +0\n\nPuedes utilizar una acción adicional para pronunciar la palabra de activación de esta espada mágica, lo que cubrirá su hoja de llamas. Estas llamas emiten luz brillante en un radio de 12 m y luz tenue 12 m más allá. Mientras la espada esté envuelta en llamas, infligirá 2d6 de daño de fuego adicional a cualquier objetivo al que impacte. Las llamas duran hasta que utilices una acción adicional para volver a pronunciar la palabra de activación o hasta que sueltes o envaines la espada.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_6124846e52dfb250$::jsonb,true),'{inventory,6,features}',$text_010aa9920d571615$[{"id":"flaming-toggle","kind":"bonus-action","name":"Encender o apagar la hoja","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Puedes utilizar una acción adicional para pronunciar la palabra de activación de esta espada mágica, lo que cubrirá su hoja de llamas. Estas llamas emiten luz brillante en un radio de 12 m y luz tenue 12 m más allá. Mientras la espada esté envuelta en llamas, infligirá 2d6 de daño de fuego adicional a cualquier objetivo al que impacte. Las llamas duran hasta que utilices una acción adicional para volver a pronunciar la palabra de activación o hasta que sueltes o envaines la espada.\n\nPronuncia la palabra de activación como acción adicional para encender o apagar la hoja. Encendida, emite luz brillante a 40 pies y tenue otros 40 pies. Las llamas se apagan al soltarla o envainarla.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":true},{"id":"flaming-hit","kind":"other","name":"Daño con la hoja encendida","uses":null,"order":1,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"2d6"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Puedes utilizar una acción adicional para pronunciar la palabra de activación de esta espada mágica, lo que cubrirá su hoja de llamas. Estas llamas emiten luz brillante en un radio de 12 m y luz tenue 12 m más allá. Mientras la espada esté envuelta en llamas, infligirá 2d6 de daño de fuego adicional a cualquier objetivo al que impacte. Las llamas duran hasta que utilices una acción adicional para volver a pronunciar la palabra de activación o hasta que sueltes o envaines la espada.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_010aa9920d571615$::jsonb,true),'{inventory,6,rules,definition,description}',$text_73f0bf892b94aec1$[{"id":"official-table","rows":[["Espadón de lengua de fuego","50 po (solo objeto mundano base; no es el precio de la variante mágica)","6 lb","2d6 cortante","Pesada, A dos manos","+0"]],"type":"table","columns":["Objeto","Precio base","Peso","Daño base","Propiedades","Bonificación mágica"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-enchantment-0","text":"Puedes utilizar una acción adicional para pronunciar la palabra de activación de esta espada mágica, lo que cubrirá su hoja de llamas. Estas llamas emiten luz brillante en un radio de 12 m y luz tenue 12 m más allá. Mientras la espada esté envuelta en llamas, infligirá 2d6 de daño de fuego adicional a cualquier objetivo al que impacte. Las llamas duran hasta que utilices una acción adicional para volver a pronunciar la palabra de activación o hasta que sueltes o envaines la espada.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$text_73f0bf892b94aec1$::jsonb,true),'{inventory,6,catalog,revision}',$text_4e07408562bedb8b$3$text_4e07408562bedb8b$::jsonb,true),'{inventory,6,rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_b62022ae7cf860f9$["official-table","official-enchantment-0"]$text_b62022ae7cf860f9$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{inventory,6,rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='monster' and content_key='gm:monster:9a82e451-94c6-451b-a06b-821360b52a65';

update public.campaigns set state_revision=state_revision+1,state_updated_at=statement_timestamp(),updated_at=statement_timestamp() where id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd';end $text$;select 23 as batch,3 as rows,(select state_revision from public.campaigns where id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd')as revision;commit;